<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {canvasTheme} from './modules/canvasTheme';
import {canvasViewport} from '../../../packages/surface/preview';
import type {Surface} from '../../../packages/schema/index';
import type {ScreenPoint} from '../../../packages/surface/preview';
import {surfaceCornerNormals,surfaceLight,surfaceViewNormal,surfaceLightGradient,shadedColor} from '../../../packages/surface/rendering';
const props=defineProps<{mesh?:Pick<Surface,'vertices'|'faces'>;view?:{yaw:number;pitch:number};lighting?:boolean;wireframe?:boolean;outline?:Map<string,{a:ScreenPoint;b:ScreenPoint}[]>;shadows?:ScreenPoint[][];handles?:ScreenPoint[];cuts?:{key:string;a:ScreenPoint;b:ScreenPoint;color?:string}[];anchor?:ScreenPoint;draft?:ScreenPoint[];draftHoles?:ScreenPoint[][];surface?:Surface;faces:{id:string;screen:ScreenPoint[];color:string}[];markings:Map<string,{key:string;path:string;color:string;name:string}[]>;labels:{id:string;x:number;y:number;text:string}[];brushPath?:string;brushColor?:string}>();
const normals=computed(()=>props.mesh?surfaceCornerNormals(props.mesh):undefined);
const canvas=ref<HTMLCanvasElement>();let observer:ResizeObserver|undefined,frame=0;
const images=new Map<string,HTMLImageElement>();let generation=0;
async function load(){const own=++generation;images.clear();await Promise.all((props.surface?.textures??[]).map(async t=>{const image=new Image();image.src=t.png;try{await image.decode();if(own===generation){images.set(t.id,image);schedule();}}catch{}}));}
function textureTriangle(ctx:CanvasRenderingContext2D,points:ScreenPoint[],uv:number[][],image:HTMLImageElement){const [a,b,c]=uv.map(p=>({x:p[0]*image.naturalWidth,y:p[1]*image.naturalHeight})),[p,q,r]=points,det=(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);if(Math.abs(det)<1e-9)return;const ax=((q.x-p.x)*(c.y-a.y)-(r.x-p.x)*(b.y-a.y))/det,bx=((r.x-p.x)*(b.x-a.x)-(q.x-p.x)*(c.x-a.x))/det,ay=((q.y-p.y)*(c.y-a.y)-(r.y-p.y)*(b.y-a.y))/det,by=((r.y-p.y)*(b.x-a.x)-(q.y-p.y)*(c.x-a.x))/det;ctx.save();ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.closePath();ctx.clip();ctx.transform(ax,ay,bx,by,p.x-ax*a.x-bx*a.y,p.y-ay*a.x-by*a.y);ctx.drawImage(image,0,0);ctx.restore();}
function paint(){const started=performance.now();frame=0;const c=canvas.value;if(!c)return;const rect=canvasViewport(c),ratio=Math.min(devicePixelRatio,2);c.width=Math.max(1,Math.round(rect.width*ratio));c.height=Math.max(1,Math.round(rect.height*ratio));const ctx=c.getContext('2d');if(!ctx)return;ctx.setTransform(ratio,0,0,ratio,0,0);const theme=canvasTheme(c);ctx.fillStyle=theme.background;ctx.fillRect(0,0,rect.width,rect.height);const scale=Math.min(rect.width/720,rect.height/540);ctx.translate(rect.width/2,rect.height/2);ctx.scale(scale,scale);
 ctx.globalAlpha=.45;ctx.fillStyle=theme.shadow;for(const tri of props.shadows??[]){ctx.beginPath();tri.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fill();}ctx.globalAlpha=1;
 const mapped=new Map(props.surface?.textureFaces?.map(f=>[f.faceId,f]));
 for(const face of props.faces){const [a,b,d]=face.screen,corners=normals.value?.get(face.id),lights=props.lighting!==false&&props.view&&corners?corners.map(normal=>surfaceLight(surfaceViewNormal(normal,props.view!.yaw,props.view!.pitch))):[1,1,1],field=surfaceLightGradient(face.screen,lights),fill=(color:string)=>{if(!field)return shadedColor(color,lights[0]);const gradient=ctx.createLinearGradient(field.x0,field.y0,field.x1,field.y1);gradient.addColorStop(0,shadedColor(color,field.min));gradient.addColorStop(1,shadedColor(color,field.max));return gradient;};ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fillStyle=fill(face.color);ctx.globalAlpha=1;ctx.fill();const mapping=mapped.get(face.id),image=mapping?images.get(mapping.textureId):undefined;if(mapping&&image){textureTriangle(ctx,face.screen,mapping.uv,image);ctx.globalCompositeOperation='multiply';ctx.fillStyle=fill('#ffffff');ctx.fill();ctx.globalCompositeOperation='source-over';}for(const m of props.markings.get(face.id)??[]){ctx.fillStyle=fill(m.color);ctx.fill(new Path2D(m.path),'evenodd');}for(const line of props.outline?.get(face.id)??[]){ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.clip();ctx.beginPath();ctx.moveTo(line.a.x,line.a.y);ctx.lineTo(line.b.x,line.b.y);ctx.strokeStyle=theme.accent;ctx.lineWidth=1.5;ctx.stroke();ctx.restore();}if(props.wireframe){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.strokeStyle=theme.wire;ctx.lineWidth=.6;ctx.stroke();}}
 // Markings retain exact source-face projection, independent of the display LOD.
 if(props.brushPath){const path=new Path2D(props.brushPath);ctx.globalAlpha=.25;ctx.fillStyle=props.brushColor??theme.accent;ctx.fill(path);ctx.globalAlpha=1;ctx.strokeStyle=props.brushColor??theme.accent;ctx.lineWidth=1;ctx.stroke(path);}

 ctx.globalAlpha=1;ctx.strokeStyle=theme.coral;ctx.lineWidth=2;ctx.fillStyle=theme.cream;for(const line of props.cuts??[]){ctx.strokeStyle=line.color??theme.coral;ctx.beginPath();ctx.moveTo(line.a.x,line.a.y);ctx.lineTo(line.b.x,line.b.y);ctx.stroke();ctx.beginPath();ctx.arc(line.a.x,line.a.y,2.5,0,Math.PI*2);ctx.fill();}if(props.anchor){ctx.fillStyle=theme.orange;ctx.beginPath();ctx.arc(props.anchor.x,props.anchor.y,5,0,Math.PI*2);ctx.fill();}if(props.draft?.length){ctx.beginPath();props.draft.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=theme.accent;ctx.lineWidth=2;ctx.stroke();}for(const ring of props.draftHoles??[]){ctx.beginPath();ring.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=theme.accent;ctx.lineWidth=2;ctx.stroke();}ctx.fillStyle=theme.orange;for(const p of props.handles??[]){ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fill();}ctx.fillStyle=theme.ink;ctx.font='12px sans-serif';for(const label of props.labels){ctx.beginPath();ctx.arc(label.x,label.y,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle=theme.background;ctx.lineWidth=3;ctx.strokeText(label.text,label.x+6,label.y);ctx.fillText(label.text,label.x+6,label.y);}
 c.dataset.paintMs=String(performance.now()-started);c.dataset.frame=String(Number(c.dataset.frame??0)+1);
}
function schedule(){if(!frame)frame=requestAnimationFrame(paint);}
watch(()=>[props.faces,props.markings,props.outline,props.labels,props.draft,props.cuts,props.anchor,props.shadows,props.handles,props.draftHoles,props.wireframe,props.mesh,props.view,props.lighting,props.brushPath,props.brushColor],schedule,{flush:'post'});
watch(()=>props.surface?.textures,()=>void load());
onMounted(()=>{void load();observer=new ResizeObserver(schedule);observer.observe(canvas.value!);schedule();});
onBeforeUnmount(()=>{generation++;images.clear();observer?.disconnect();if(frame)cancelAnimationFrame(frame);});
</script>
<template><canvas ref="canvas" class="surface-view surface-canvas" aria-label="3D surface preview"/></template>
<style scoped>.surface-canvas{width:100%;display:block;touch-action:none;user-select:none;border:1px solid var(--border);min-height:80px}</style>
